SELECT ?p ?cls ?ts WHERE {
  ?p ref:hasLabel "HWPump02" ;
     ref:hasExternalReference ?r .
  ?r ref:hasTimeseriesId ?ts .
  ?p brick:type ?cls .
}

SELECT ?p ?cls ?ts ?label WHERE {
  ?p brick:type brick:ElectricPower .
  OPTIONAL { ?p ref:hasLabel ?label . }
  OPTIONAL { ?p ref:hasExternalReference ?r . ?r ref:hasTimeseriesId ?ts . }
} LIMIT 200

